SELECT p.gender, p.age, a.admission_type_id, a.length_of_stay, COUNT(DISTINCT p.subject_id) AS patient_count, AVG(pc.procedure_count) AS avg_procedures FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN (SELECT subject_id, COUNT(*) AS procedure_count FROM procedures_icd GROUP BY subject_id) AS pc ON a.subject_id = pc.subject_id WHERE p.gender = 'M' AND p.age BETWEEN 42 AND 52 AND a.admission_type_id = 1 AND a.length_of_stay BETWEEN 1 AND 4 AND pc.procedure_count BETWEEN 1 AND 7 GROUP BY p.gender, p.age, a.admission_type_id, a.length_of_stay ORDER BY p.gender, p.age, a.admission_type_id, a.length_of_stay NULLS LAST;